<template>  <view class="page">    <!-- ========== 顶部：总价 ========== -->    <view class="total-card">      <text class="total-label">合计</text>      <text class="total-price">¥ {{ totalPrice.toFixed(2) }}</text>      <text class="total-hint">共 {{ totalCount }} 件商品</text>    </view>     <!-- ========== 三个水果：同一个组件用三次 ========== -->    <view class="list">      <view class="row" v-for="item in fruits" :key="item.id">        <view class="row-left">          <text class="emoji">{{ item.emoji }}</text>          <view class="row-text">            <text class="name">{{ item.name }}</text>            <text class="price">¥ {{ item.price.toFixed(2) }} / 斤</text>          </view>        </view>
		 <!--          easycom：没写 import，没在 components 里注册，          直接 <Stepper /> 就能用        -->        <Stepper          :initial-value="item.initial"          :min="0"          :max="20"          @change="(val) => onChange(item.id, val)"        />      </view>    </view>     <!-- ========== 第四个：演示具名插槽 ========== -->    <view class="slot-demo">      <view class="slot-title">        <text>插槽演示：换掉加减按钮</text>      </view>
	  
	   <view class="row">        <view class="row-left">          <text class="emoji">🍇</text>          <view class="row-text">            <text class="name">葡萄（自定义按钮）</text>            <text class="price">¥ {{ grape.price.toFixed(2) }} / 斤</text>          </view>        </view>         <!-- 骨架不变，把减号加号换成自定义文字 -->        <Stepper          :initial-value="grape.initial"          :min="0"          :max="10"          @change="onGrapeChange"        >          <template #prefix>            <text class="slot-btn slot-minus">－</text>          </template>          <template #suffix>            <text class="slot-btn slot-plus">＋</text>          </template>        </Stepper>
		
		<script setup>import { ref, computed, reactive } from 'vue'import { fruits } from '../../src/data/fruits.js' // ---------- 1. 每个水果当前的数量 ----------const counts = reactive({}) fruits.forEach(item => {  counts[item.id] = item.initial}) // ---------- 2. ⭐ 总价：computed 自动跟着 counts 变 ----------const totalPrice = computed(() => {  return fruits.reduce((sum, item) => {    return sum + (counts[item.id] || 0) * item.price  }, 0)}) const totalCount = computed(() => {  return fruits.reduce((sum, item) => sum + (counts[item.id] || 0), 0)})
// ---------- 3. 接收子组件的 emit ----------function onChange(id, newValue) {  counts[id] = newValue  console.log('[父组件] 收到 change：id =', id, '新值 =', newValue)} // ---------- 4. 插槽示例：葡萄的数量 ----------const grape = reactive({ price: 12.8, initial: 1 })const grapeCount = ref(1) function onGrapeChange(val) {  grapeCount.value = val} // ---------- 5. 重置 ----------function resetAll() {  fruits.forEach(item => {    counts[item.id] = item.initial  })  grapeCount.value = grape.initial  uni.showToast({ title: '已重置', icon: 'success' })}</script>


